import java.util.Scanner;

public class Main {
    static long[] ones = new long[20];
    static long[] powers = new long[20];
    static int min_moves = -1;

    static void prepare() {
        powers[0] = 1;
        for (int i = 1; i <= 17; ++i)
            powers[i] = powers[i - 1] * 10;

        ones[0] = 0;
        for (int i = 1; i <= 17; ++i)
            ones[i] = ones[i - 1] * 10 + 1;
    }

    static int get_length(long num) {
        int len = 0;
        do {
            ++len;
            num /= 10;
        } while (num != 0);
        return len;
    }

    static void recurse(int digit_pos, long val, int steps) {
        if (min_moves != -1 && steps >= min_moves)
            return;
        if (val == 0 || digit_pos == 0) {
            if (min_moves == -1 || steps < min_moves)
                min_moves = steps;
            return;
        }
        if (val < 0)
            val = -val;

        long temp_val = val;
        int temp_steps = 0;
        while (temp_val >= powers[digit_pos - 1]) {
            temp_val -= ones[digit_pos];
            temp_steps += digit_pos;
        }
        recurse(digit_pos - 1, temp_val, steps + temp_steps);

        temp_val = ones[digit_pos + 1] - val;
        temp_steps = 0;
        while (temp_val >= powers[digit_pos - 1]) {
            temp_val -= ones[digit_pos];
            temp_steps += digit_pos;
        }
        recurse(digit_pos - 1, temp_val, steps + digit_pos + 1 + temp_steps);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        prepare();

        long number = sc.nextLong();
        min_moves = -1;
        recurse(get_length(number), number, 0);
        System.out.println(min_moves);
        sc.close();
    }
}
